285	In `src/textstats.js`, replace the line `module.exports = { wordCount };` with the following block. Everything above that line stays as it is.
286	
287	```javascript
288	// Words whose trailing period does not end a sentence. Compared lower-case and
289	// without any opening bracket or quote. "U.S.A." style initialisms are not
290	// listed: they usually do end a sentence when they come last, and guessing
291	// otherwise would trade one error for another.
292	const ABBREVIATIONS = new Set(['mr', 'mrs', 'ms', 'dr', 'prof', 'st', 'sr', 'jr', 'vs', 'e.g', 'i.e']);
293	
294	// A terminator run ("." "?!" "...") plus any closing quotes or brackets, and
295	// only where whitespace or the end of the text follows. Requiring that keeps
296	// decimals ("3.14"), domains ("example.com") and "a.b.c" in one piece.
297	const TERMINATOR_PATTERN = /([.!?]+)(["'”’)\]]*)(?=\s|$)/g;
298	
299	function endsWithAbbreviation(before) {
300	  const last = before.match(/(\S+)$/);
301	  if (last === null) {
302	    return false;
303	  }
304	  const word = last[1].replace(/^["'“‘(\[]+/, '').toLowerCase();
305	  return ABBREVIATIONS.has(word);
306	}
307	
308	/**
309	 * Count the sentences in a piece of text.
310	 *
311	 * A sentence is a stretch of text containing at least one word and ending at a
312	 * terminator run, or at the end of the text. A lone period after a known
313	 * abbreviation does not end a sentence.
314	 *
315	 * @param {string} text
316	 * @returns {number}
317	 */
318	function sentenceCount(text) {
319	  assertText('sentenceCount', text);
320	  let count = 0;
321	  let start = 0;
322	  for (const match of text.matchAll(TERMINATOR_PATTERN)) {
323	    const before = text.slice(start, match.index);
324	    if (match[1] === '.' && endsWithAbbreviation(before)) {
325	      continue;
326	    }
327	    if (tokenize(before).length > 0) {
328	      count += 1;
329	    }
330	    start = match.index + match[0].length;
331	  }
332	  if (tokenize(text.slice(start)).length > 0) {
333	    count += 1;
334	  }
335	  return count;
336	}
337	
338	module.exports = { wordCount, sentenceCount };
339	```
