  2	const assert = require('node:assert/strict');
  3	const { topWords } = require('../src/textstats');
  4	
  5	// Counted by hand: "keeper" x3, "lamp" x3, "night" x2, "tower" x2, then seven
  6	// words once each in code-unit order: climbed, hand, lit, old, older, shook,
  7	// storm. Stop words (the, a, of, and, on, in, was) are present on purpose and
  8	// must not appear.
  9	const PASSAGE = [
 10	  'The keeper lit the lamp. The lamp was old, and the keeper was older.',
 11	  'On a night of storm the tower shook; in the night the keeper climbed',
 12	  'the tower, lamp in hand.',
 13	].join(' ');
 14	
 15	const CASES = [
 16	  ["apple", 1, [{"word": "apple", "count": 1}]],
 17	  ["apple apple", 1, [{"word": "apple", "count": 2}]],
 18	  ["apple banana", 5, [{"word": "apple", "count": 1}, {"word": "banana", "count": 1}]],
 19	  ["banana apple", 5, [{"word": "apple", "count": 1}, {"word": "banana", "count": 1}]],
 20	  ["fig fig pear", 1, [{"word": "fig", "count": 2}]],
 21	  ["fig fig pear", 2, [{"word": "fig", "count": 2}, {"word": "pear", "count": 1}]],
 22	  ["kiwi kiwi lime lime", 2, [{"word": "kiwi", "count": 2}, {"word": "lime", "count": 2}]],
 23	  ["x y z", 2, [{"word": "x", "count": 1}, {"word": "y", "count": 1}]],
 24	];
 25	
 26	test('returns an empty array for the empty string', () => {
 27	  assert.deepEqual(topWords('', 5), []);
 28	});
 29	
 30	test('returns an empty array for punctuation and whitespace only', () => {
 31	  assert.deepEqual(topWords(' ... -- ?! \n', 5), []);
 32	});
 33	
 34	test('returns an empty array when every word is a stop word', () => {
 35	  assert.deepEqual(topWords('the and of the to a in it', 5), []);
 36	});
 37	
 38	test('returns an empty array when n is 0', () => {
 39	  assert.deepEqual(topWords('apple banana apple', 0), []);
 40	});
 41	
 42	test('returns word and count pairs', () => {
 43	  assert.deepEqual(topWords('apple', 1), [{ word: 'apple', count: 1 }]);
 44	});
 45	
 46	test('orders words by count, highest first', () => {
 47	  assert.deepEqual(topWords('pear apple apple fig fig fig', 3), [
 48	    { word: 'fig', count: 3 },
 49	    { word: 'apple', count: 2 },
 50	    { word: 'pear', count: 1 },
 51	  ]);
 52	});
 53	
 54	test('throws a TypeError naming the function for a non-string', () => {
 55	  for (const bad of [undefined, null, 3, {}, ['apple']]) {
 56	    assert.throws(() => topWords(bad, 3), (err) => {
 57	      assert.ok(err instanceof TypeError);
 58	      assert.ok(err.message.startsWith('topWords:'));
 59	      return true;
 60	    });
 61	  }
 62	});
 63	
 64	test('matches every row of the reference table', () => {
 65	  for (const [text, n, expected] of CASES) {
 66	    assert.deepEqual(topWords(text, n), expected, JSON.stringify([text, n]));
 67	  }
 68	});
 69	
 70	test('ranks the passage by count, then by code unit within a count', () => {
 71	  assert.deepEqual(topWords(PASSAGE, 4), [
 72	    { word: 'keeper', count: 3 },
 73	    { word: 'lamp', count: 3 },
 74	    { word: 'night', count: 2 },
 75	    { word: 'tower', count: 2 },
 76	  ]);
 77	  assert.deepEqual(topWords(PASSAGE, 100), [
 78	    { word: 'keeper', count: 3 },
 79	    { word: 'lamp', count: 3 },
 80	    { word: 'night', count: 2 },
 81	    { word: 'tower', count: 2 },
 82	    { word: 'climbed', count: 1 },
 83	    { word: 'hand', count: 1 },
 84	    { word: 'lit', count: 1 },
 85	    { word: 'old', count: 1 },
 86	    { word: 'older', count: 1 },
 87	    { word: 'shook', count: 1 },
 88	    { word: 'storm', count: 1 },
 89	  ]);
 90	});
 91	
 92	test('leaves the passage stop words out of the full result', () => {
 93	  const words = topWords(PASSAGE, 100).map((entry) => entry.word);
 94	  for (const stop of ['the', 'a', 'of', 'and', 'on', 'in', 'was']) {
 95	    assert.ok(!words.includes(stop), stop);
 96	  }
 97	});
 98	
 99	test('folds case with toLowerCase, including accented letters', () => {
100	  assert.deepEqual(topWords('Éclair éclair ÉCLAIR Apple', 5), [
101	    { word: 'éclair', count: 3 },
102	    { word: 'apple', count: 1 },
103	  ]);
104	});
105	
106	test('folds the typographic apostrophe into the straight one', () => {
107	  assert.deepEqual(topWords("keeper’s keeper's", 5), [{ word: "keeper's", count: 2 }]);
108	});
109	
110	test('keeps hyphenated compounds, contractions and numbers as words', () => {
111	  assert.deepEqual(topWords("well-known don't 42 well-known", 5), [
112	    { word: 'well-known', count: 2 },
113	    { word: '42', count: 1 },
114	    { word: "don't", count: 1 },
115	  ]);
116	});
117	
118	test('skips stop words after folding', () => {
119	  assert.deepEqual(topWords('The THE the Apple', 5), [{ word: 'apple', count: 1 }]);
120	});
121	
122	test('breaks ties by code unit, not by locale', () => {
123	  // Code-unit order puts "z" before "é"; a locale comparison would not.
124	  assert.deepEqual(topWords('é z e', 5), [
125	    { word: 'e', count: 1 },
126	    { word: 'z', count: 1 },
127	    { word: 'é', count: 1 },
128	  ]);
129	});
130	
131	test('returns every distinct word when n is larger than their number', () => {
132	  assert.deepEqual(topWords('pear apple apple', 99), [
133	    { word: 'apple', count: 2 },
134	    { word: 'pear', count: 1 },
135	  ]);
136	});
137	
138	test('throws a RangeError naming the function for an invalid n', () => {
139	  for (const bad of [undefined, NaN, '3', 1.5, -1]) {
140	    assert.throws(() => topWords('apple', bad), (err) => {
141	      assert.ok(err instanceof RangeError);
142	      assert.ok(err.message.startsWith('topWords:'));
143	      return true;
144	    });
145	  }
146	});
147	
148	test('checks the text before n', () => {
149	  assert.throws(() => topWords(5, 'bad'), (err) => {
150	    assert.ok(err instanceof TypeError);
151	    assert.ok(err.message.startsWith('topWords:'));
152	    return true;
153	  });
154	});
155	
156	test('returns fresh objects on every call', () => {
157	  const first = topWords('apple apple pear', 2);
158	  first[0].count = 99;
159	  first[1].word = 'changed';
160	  first.pop();
161	  assert.deepEqual(topWords('apple apple pear', 2), [
162	    { word: 'apple', count: 2 },
163	    { word: 'pear', count: 1 },
164	  ]);
165	});
  1	const { test } = require('node:test');
  2	const assert = require('node:assert/strict');
  3	const { readingTimeMinutes, wordCount } = require('../src/textstats');
  4	
  5	// n copies of a one-word token, so the word count is exactly n.
  6	const words = (n) => Array.from({ length: n }, () => 'word').join(' ');
  7	
  8	const CASES = [
  9	  ["", null, 0],
 10	  ["x", null, 1],
 11	  ["x x", null, 1],
 12	  ["", 50, 0],
 13	  ["x", 1, 1],
 14	  ["x x", 1, 2],
 15	  ["x x x", 1, 3],
 16	  ["x x x", 2, 2],
 17	];
 18	
 19	test('returns 0 for the empty string', () => {
 20	  assert.equal(readingTimeMinutes(''), 0);
 21	});
 22	
 23	test('returns 0 for whitespace and punctuation only', () => {
 24	  assert.equal(readingTimeMinutes(' \n -- ... '), 0);
 25	});
 26	
 27	test('rounds a single word up to one minute', () => {
 28	  assert.equal(readingTimeMinutes('hello'), 1);
 29	});
 30	
 31	test('returns 1 for exactly 200 words at the default rate', () => {
 32	  assert.equal(readingTimeMinutes(words(200)), 1);
 33	});
 34	
 35	test('returns 2 for 201 words at the default rate', () => {
 36	  assert.equal(readingTimeMinutes(words(201)), 2);
 37	});
 38	
 39	test('returns 2 for exactly 400 words at the default rate', () => {
 40	  assert.equal(readingTimeMinutes(words(400)), 2);
 41	});
 42	
 43	test('throws a TypeError naming the function for a non-string', () => {
 44	  for (const bad of [undefined, null, 12, {}, ['a b']]) {
 45	    assert.throws(() => readingTimeMinutes(bad), (err) => {
 46	      assert.ok(err instanceof TypeError);
 47	      assert.ok(err.message.startsWith('readingTimeMinutes:'));
 48	      return true;
 49	    });
 50	  }
 51	});
 52	
 53	test('matches every row of the reference table', () => {
 54	  for (const [text, wpm, expected] of CASES) {
 55	    const actual = wpm === null ? readingTimeMinutes(text) : readingTimeMinutes(text, wpm);
 56	    assert.equal(actual, expected, JSON.stringify([text, wpm]));
 57	  }
 58	});
 59	
 60	test('rounds three paragraphs of a nine-word sentence up to two minutes', () => {
 61	  const sentence = 'the quick brown fox jumps over the lazy dog';
 62	  const paragraph = Array.from({ length: 10 }, () => sentence).join(' ');
 63	  const text = [paragraph, paragraph, paragraph].join('\n\n');
 64	  assert.equal(wordCount(text), 270);
 65	  assert.equal(readingTimeMinutes(text), 2);
 66	});
 67	
 68	test('treats an explicit undefined rate as the default of 200', () => {
 69	  assert.equal(readingTimeMinutes(words(201), undefined), 2);
 70	  assert.equal(readingTimeMinutes(words(200), undefined), 1);
 71	});
 72	
 73	test('allows a fractional rate', () => {
 74	  // 301 / 150.5 = 2 exactly. Truncated to 150 it would be 301 / 150 = 2.007, so 3.
 75	  assert.equal(readingTimeMinutes(words(301), 150.5), 2);
 76	  assert.equal(readingTimeMinutes(words(302), 150.5), 3);
 77	  // 3 / 0.5 = 6; truncated to 0 it would be Infinity.
 78	  assert.equal(readingTimeMinutes(words(3), 0.5), 6);
 79	});
 80	
 81	test('throws a RangeError naming the function for an invalid rate', () => {
 82	  for (const bad of [0, -1, -200, NaN, Infinity, -Infinity, '200', null]) {
 83	    assert.throws(() => readingTimeMinutes('hello world', bad), (err) => {
 84	      assert.ok(err instanceof RangeError, String(bad));
 85	      assert.ok(err.message.startsWith('readingTimeMinutes:'), String(bad));
 86	      return true;
 87	    });
 88	  }
 89	});
 90	
 91	test('checks the text before the rate', () => {
 92	  for (const badWpm of [0, NaN, '200', null]) {
