 94	      assert.ok(err instanceof TypeError);
 95	      assert.ok(err.message.startsWith('readingTimeMinutes:'));
 96	      return true;
 97	    });
 98	  }
 99	});
100	
101	test('counts hyphenated compounds, contractions and decimals as wordCount does', () => {
102	  // A(1) well-known(2) rule(3) don't(4) round(5) 3(6) 14(7) up(8): 8 words.
103	  const text = "A well-known rule: don't round 3.14 up.";
104	  assert.equal(readingTimeMinutes(text, 1), 8);
105	  assert.equal(readingTimeMinutes(text, 1), wordCount(text));
106	});

